import collections, datetime, json, pathlib, sqlite3

DB_PATH = pathlib.Path(r'D:\repository\数据湖\分析产出\持仓面板\holding.sqlite')
BACKUP_PATH = pathlib.Path(r'D:\repository\数据湖\.task-state\panel-sync-before.sqlite')
CONFIG_PATH = pathlib.Path(r'D:\repository\数据湖\分析产出\持仓面板\config.js')
KEYS = ('cfg', 'cfgSyncedAt', 'cfgSource')
text = CONFIG_PATH.read_text(encoding='utf-8')
marker = 'window.PANEL_CONFIG = '
start = text.find(marker)
if start < 0:
    raise RuntimeError('config.js 中未找到 PANEL_CONFIG 赋值')
payload = text[start + len(marker):].strip()
if not payload.endswith(';'):
    raise RuntimeError('config.js JSON 终止符不符')
config = json.loads(payload[:-1].strip())
config_value = json.dumps(config, ensure_ascii=False, separators=(',', ':'), allow_nan=False)
timestamp = datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds').replace('+00:00', 'Z')
expected = {'cfg': config_value, 'cfgSyncedAt': timestamp, 'cfgSource': 'sync'}
backup = sqlite3.connect(str(BACKUP_PATH))
db = sqlite3.connect(str(DB_PATH))
def schema(conn):
    return conn.execute('SELECT type,name,tbl_name,sql FROM sqlite_master ORDER BY type,name').fetchall()
def table_names(conn):
    return [r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")]
def table_rows(conn, name):
    if name == 'setting':
        return collections.Counter(conn.execute('SELECT * FROM setting WHERE k NOT IN (?,?,?)', KEYS).fetchall())
    quoted = '"' + name.replace('"', '""') + '"'
    return collections.Counter(conn.execute(f'SELECT * FROM {quoted}').fetchall())
def verify_untouched():
    if schema(db) != schema(backup):
        raise RuntimeError('数据库 schema 与备份不同')
    current_tables, backup_tables = table_names(db), table_names(backup)
    if current_tables != backup_tables:
        raise RuntimeError('数据库表列表与备份不同')
    for name in current_tables:
        if table_rows(db, name) != table_rows(backup, name):
            raise RuntimeError(f'非目标数据与备份不同：{name}')
def quick_check(conn):
    result = conn.execute('PRAGMA quick_check').fetchone()
    if not result or result[0] != 'ok':
        raise RuntimeError(f'SQLite quick_check 失败：{result}')
try:
    quick_check(backup)
    quick_check(db)
    verify_untouched()
    old_live = dict(db.execute('SELECT k,v FROM setting WHERE k IN (?,?,?)', KEYS).fetchall())
    old_backup = dict(backup.execute('SELECT k,v FROM setting WHERE k IN (?,?,?)', KEYS).fetchall())
    if set(old_live) != set(KEYS) or old_live != old_backup:
        raise RuntimeError('三个目标键缺失或当前值已偏离备份')
    before_changes = db.total_changes
    db.execute('BEGIN IMMEDIATE')
    try:
        cursor = db.executemany('UPDATE setting SET v=? WHERE k=?', [(expected[k], k) for k in KEYS])
        if cursor.rowcount != 3 or db.total_changes - before_changes != 3:
            raise RuntimeError(f'更新行数不是3，已计变更={db.total_changes - before_changes}')
        if dict(db.execute('SELECT k,v FROM setting WHERE k IN (?,?,?)', KEYS).fetchall()) != expected:
            raise RuntimeError('事务内目标键值校验失败')
        verify_untouched()
        quick_check(db)
        db.commit()
    except Exception:
        db.rollback()
        raise
    if dict(db.execute('SELECT k,v FROM setting WHERE k IN (?,?,?)', KEYS).fetchall()) != expected:
        raise RuntimeError('提交后目标键值校验失败')
    verify_untouched()
    quick_check(db)
    print(f'已更新并验证3个 setting 键；cfg 长度={len(config_value)}；cfgSyncedAt={timestamp}；其他表及其他 setting 键与备份一致。')
finally:
    db.close()
    backup.close()
'@
